import { execFileSync } from 'child_process';
import { subprocessEnvironment } from './subprocessEnvironment';
import fs from 'fs';
import path from 'path';
import { createLogger } from './logger';
import { hostShell } from './hostShell';

const log = createLogger('LoginShellPath');


const SENTINEL = '__RIVET_PATH__';

const rcFileForShell = (shell: string): string | null => {
  const name = path.basename(shell);
  if (name === 'zsh') return '~/.zshrc';
  if (name === 'bash') return '~/.bashrc';
  return null;
};

export type ShellExec = (
  shell: string,
  args: string[],
) => string;

const defaultExec: ShellExec = (shell, args) =>
  execFileSync(shell, args, {
    timeout: 4_000,
    env: subprocessEnvironment('verifier'),
    stdio: ['ignore', 'pipe', 'ignore'],
    encoding: 'utf8',
  });

const PRINT_PATH = `printf "%s%s%s" "${SENTINEL}" "$PATH" "${SENTINEL}"`;

const DEFAULT_GOAL_BINARIES = ['claude', 'node'];

export const isBinaryOnPathValue = (
  binary: string,
  pathValue: string,
): boolean =>
  pathValue.split(':').some((dir) => {
    if (!dir) return false;
    try {
      fs.accessSync(path.join(dir, binary), fs.constants.X_OK);
      return true;
    } catch {
      return false;
    }
  });

export const loginShellPath = (
  options?: {
    exec?: ShellExec;
    shell?: string;
    basePath?: string;
    goalBinaries?: string[];
  },
): string | null => {
  if (process.platform === 'win32') return null;
  const shell = options?.shell ?? hostShell();
  const exec = options?.exec ?? defaultExec;
  const basePath = options?.basePath ?? process.env.PATH ?? '';
  const goalBinaries = options?.goalBinaries ?? DEFAULT_GOAL_BINARIES;
  const rcFile = rcFileForShell(shell);
  const probes: string[][] = [
    ['-lc', PRINT_PATH],
    ...(rcFile
      ? [['-lc', `. ${rcFile} >/dev/null 2>&1 || true; ${PRINT_PATH}`]]
      : []),
    ['-ilc', PRINT_PATH],
  ];
  let union = '';
  for (const args of probes) {
    let value: string | undefined;
    try {
      const output = exec(shell, args);
      value = output
        .match(new RegExp(`${SENTINEL}([\\s\\S]*?)${SENTINEL}`))?.[1]
        ?.trim();
    } catch (error) {
      log.warn(
        `login-shell PATH probe (${args[0]}) failed for ${shell}`,
        error instanceof Error ? error.message : error,
      );
      continue;
    }
    if (!value) continue;
    union = union ? mergePathValues(union, value) : value;
    if (areBinariesOnPathValue(goalBinaries, mergePathValues(basePath, union))) {
      break;
    }
  }
  return union || null;
};

const areBinariesOnPathValue = (
  binaries: string[],
  pathValue: string,
): boolean => binaries.every((binary) => isBinaryOnPathValue(binary, pathValue));

export const mergePathValues = (base: string, extra: string): string => {
  const baseDirs = base.split(':').filter(Boolean);
  const seen = new Set(baseDirs);
  const additions = extra.split(':').filter((dir) => dir && !seen.has(dir));
  return [...baseDirs, ...additions].join(':');
};

const APPLIED_ENV_FLAG = 'RIVET_LOGIN_SHELL_PATH_APPLIED';

let enriched = false;
export const ensureLoginShellPath = (
  options?: { exec?: ShellExec; shell?: string; goalBinaries?: string[] },
): void => {
  if (enriched) return;
  enriched = true;
  if (process.env[APPLIED_ENV_FLAG] === '1') return;
  const current = process.env.PATH ?? '';
  if (
    areBinariesOnPathValue(
      options?.goalBinaries ?? DEFAULT_GOAL_BINARIES,
      current,
    )
  ) {
    process.env[APPLIED_ENV_FLAG] = '1';
    return;
  }
  const shellPath = loginShellPath({ ...options, basePath: current });
  if (!shellPath) return;
  process.env[APPLIED_ENV_FLAG] = '1';
  const merged = mergePathValues(current, shellPath);
  if (merged !== current) {
    log.info(
      `merged ${merged.split(':').length - current.split(':').filter(Boolean).length} login-shell PATH entries into the server environment`,
    );
    process.env.PATH = merged;
  }
};

export const resetLoginShellPathForTests = (): void => {
  enriched = false;
  delete process.env[APPLIED_ENV_FLAG];
};
